const cfg=$('Config').first().json;
const staticData=$getWorkflowStaticData('global');
staticData.seen=staticData.seen||{};
const mail=items[0].json;
const subject=String(mail.subject||'');
const body=String(mail.textHtml||mail.html||mail.textPlain||mail.text||'');
const blob=`${subject}\n${body}`.toLowerCase();
const keys=(cfg.areaKeywords||['roscrea']).map(s=>String(s).toLowerCase());
if(!keys.some(k=>blob.includes(k))) return [];
const urls=[...`${subject}\n${body}`.matchAll(/https?:\/\/(?:www\.)?daft\.ie\/[^\s"'<>]+/gi)].map(m=>m[0].replace(/[),.;]+$/,''));
const uniq=[...new Set(urls)].filter(u=>/for-rent|sharing|property-for-rent/i.test(u));
const out=[];
for (const url of uniq){
  const idMatch=url.match(/(\d{6,})/);
  const id=`daft-mail-${idMatch?idMatch[1]:url}`;
  if(staticData.seen[id]) continue;
  out.push({json:{...cfg,id,source:'daft-email',title:subject||'Daft alert',price:'',beds:'',propertyType:'',seller:'',url,detectedAtMs:Date.now()}});
}
return out;

const staticData=$getWorkflowStaticData('global');
staticData.seen=staticData.seen||{};
const cfg=$('Config').first().json;
const candidate=$('Has Links?').item.json;
const htmlRaw=items[0].json;
const html=typeof htmlRaw==='string'?htmlRaw:(htmlRaw.data||htmlRaw.body||htmlRaw.html||'');
const t=String(html||'');
if(!t||/no longer available|this ad has been removed|ad has expired/i.test(t)){staticData.seen[candidate.id]=Date.now();return [];}
let title=candidate.title, price=candidate.price, seller='', beds='', propertyType='', url=candidate.url;
const m=t.match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
if(m){
  try{
    const data=JSON.parse(m[1]);
    const listing=(((data||{}).props||{}).pageProps||{}).listing;
    if(listing){
      if(listing.state && String(listing.state).toUpperCase()!=='PUBLISHED'){staticData.seen[candidate.id]=Date.now();return [];}
      title=listing.title||title; price=listing.price||price; seller=(listing.seller&&listing.seller.name)||''; beds=listing.numBedrooms||''; propertyType=listing.propertyType||'';
      if(listing.seoFriendlyPath) url=`https://www.daft.ie${listing.seoFriendlyPath}`;
    }
  }catch(e){}
}
const keys=(cfg.areaKeywords||['roscrea']).map(s=>String(s).toLowerCase());
const blob=`${title} ${url}`.toLowerCase();
if(!keys.some(k=>blob.includes(k))) return [];
const bedNum=(String(beds).match(/(\d+)/)||[])[1];
if(Number(cfg.minBeds||0)>0 && bedNum && Number(bedNum)<Number(cfg.minBeds)) return [];
staticData.seen[candidate.id]=Date.now();
const detectedAtMs=candidate.detectedAtMs||Date.now();
const detected=new Date(detectedAtMs).toLocaleTimeString('en-IE',{hour12:false,timeZone:'Europe/Dublin'});
const ageSec=Math.max(0,Math.round((Date.now()-detectedAtMs)/1000));
const text=[
`🚨 NEW PROPERTY`,` `,`🏠 ${beds||'? Bed'} ${propertyType||'Property'}`,`📍 ${title}`,`💶 ${price||'See ad'}`,`🕐 detected: ${detected}`,`🟢 NEW — ${ageSec} seconds ago`,`📡 daft-email`,`✅ LIVE verified`,` `,`🔗 ${url}`,` `,`ACTION:`,`1) Open`,`2) Call if phone visible`,`3) Else Enquire NOW`
].join('\n');
return [{json:{id:candidate.id,title,price,beds,propertyType,seller,url,source:'daft-email',telegramChatId:cfg.telegramChatId,text,status:'available',foundAt:new Date().toISOString()}}];
